import sys
def solve(n, pts):
    MOD = 998244353
    X = [p[0] for p in pts]; Y = [p[1] for p in pts]
    colBits = [0]*(n+2); rowBits = [0]*(n+2)
    for i in range(n):
        colBits[X[i]] |= 1<<i; rowBits[Y[i]] |= 1<<i
    prefX = [0]*(n+2); prefY = [0]*(n+2)
    for v in range(1, n+1):
        prefX[v] = prefX[v-1] | colBits[v]
        prefY[v] = prefY[v-1] | rowBits[v]
    def pref(arr, v):
        if v <= 0: return 0
        if v > n: v = n
        return arr[v]
    def rng(arr, lo, hi):
        return pref(arr, hi-1) & ~pref(arr, lo)
    adj = [0]*n
    for i in range(n):
        m = 0
        for j in range(n):
            if j != i and (X[j]-X[i])*(Y[j]-Y[i]) > 0:
                m |= 1<<j
        adj[i] = m
    def ok(xa, ya, xb, yb):
        S = rng(prefX, xa, xb) & rng(prefY, yb, ya)
        s = S
        while s:
            low = s & -s
            i = low.bit_length()-1
            if adj[i] & S == 0:
                return False
            s ^= low
        return True
    order = sorted(range(n), key=lambda i: X[i])
    dp = [0]*n
    for i in order:
        v = 1 if ok(0, n+1, X[i], Y[i]) else 0
        tot = v
        for a in range(n):
            if X[a] < X[i] and Y[a] > Y[i] and dp[a]:
                if ok(X[a], Y[a], X[i], Y[i]):
                    tot += dp[a]
        dp[i] = tot % MOD
    total = 0
    for i in range(n):
        if dp[i] and ok(X[i], Y[i], n+1, 0):
            total += dp[i]
    total %= MOD
    P0 = [i for i in range(n) if all(j == i or (X[j]-X[i])*(Y[j]-Y[i]) < 0 for j in range(n))]
    full_covered = False
    if P0:
        P0.sort(key=lambda i: X[i])
        seq = [(0, n+1)] + [(X[i], Y[i]) for i in P0] + [(n+1, 0)]
        good = True
        for k in range(len(seq)-1):
            if not ok(seq[k][0], seq[k][1], seq[k+1][0], seq[k+1][1]):
                good = False; break
        full_covered = good
    if not full_covered:
        total += 1
    return total % MOD

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    pts = [(int(data[1+2*i]), int(data[2+2*i])) for i in range(n)]
    print(solve(n, pts))
if __name__ == "__main__":
    main()

