import random, itertools
def reach(P):
    n=len(P); full=(1<<n)-1
    seen={full}; st=[full]
    while st:
        S=st.pop()
        for k in range(n):
            if S>>k&1:
                T=1<<k
                for i in range(n):
                    if i!=k and S>>i&1:
                        if (P[i][0]-P[k][0])*(P[i][1]-P[k][1])<0: T|=1<<i
                if T not in seen: seen.add(T); st.append(T)
    return seen
def depth_ok(P):
    # check if reachable sets are all reachable in <=2 ops from full
    n=len(P); full=(1<<n)-1
    def op(S,k):
        T=1<<k
        for i in range(n):
            if i!=k and S>>i&1 and (P[i][0]-P[k][0])*(P[i][1]-P[k][1])<0: T|=1<<i
        return T
    lvl1={op(full,k) for k in range(n)}|{full}
    lvl2=set(lvl1)
    for S in lvl1:
        for k in range(n):
            if S>>k&1: lvl2.add(op(S,k))
    return len(reach(P))==len(lvl2), len(reach(P))
