from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_b = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = min(x, y), max(x, y)
            by_b[b].append((a, idx))
        gain = [0] * len(conflictingPairs)
        m1 = 0; i1 = -1; m2 = 0
        base = 0
        for r in range(1, n + 1):
            for a, idx in by_b[r]:
                if a > m1:
                    m2 = m1
                    m1 = a
                    i1 = idx
                elif a > m2:
                    m2 = a
            base += r - m1
            if i1 >= 0:
                gain[i1] += m1 - m2
        return base + max(gain)

