import time
def insert_shape(T, x):
    rows=[list(r) for r in T]
    r=0
    while True:
        if r==len(rows):
            rows.append([x]); return (r,0)
        row=rows[r]
        lo,hi=0,len(row)
        while lo<hi:
            m=(lo+hi)//2
            if row[m]>x: hi=m
            else: lo=m+1
        if lo==len(row):
            row.append(x); return (r,lo)
        row[lo],x=x,row[lo]
        r+=1
def g(A,B):
    shape=[A]*B; shape[-1]-=1
    N=A*B-1
    cnt=0
    rows=[[] for _ in shape]
    def check():
        for t in range(N+1):
            TT=[[2*v for v in r] for r in rows]
            if insert_shape(TT,2*t+1)==(B-1,A-1): return True
        return False
    def rec(k):
        nonlocal cnt
        if k>N:
            cnt+=check(); return
        for i in range(B):
            if len(rows[i])<shape[i] and (i==0 or len(rows[i-1])>len(rows[i])):
                rows[i].append(k); rec(k+1); rows[i].pop()
    rec(1)
    return cnt
