import sys

def solve(N, A):
    A = [0] + A
    L = [0]*(N+1); seen = set()
    for i in range(1, N+1):
        seen.add(A[i]); L[i] = len(seen)
    R = [0]*(N+2); seen = set()
    for j in range(N, 0, -1):
        R[j] = len(seen); seen.add(A[j])
    prv = [0]*(N+1); last = {}
    for j in range(1, N+1):
        prv[j] = last.get(A[j], 0); last[A[j]] = j
    par = list(range(N+2))
    pred = [-1]*(N+2)
    gap = [0]*(N+2)
    maxval = 0; Vlast = 0; tail = -1
    ans = 0
    def find(x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x
    for j in range(2, N):
        e = j - 1
        v0 = L[e]
        if tail == -1:
            maxval = v0; pred[e] = -1
        else:
            c = tail; Vc = Vlast
            while c != -1 and Vc <= v0:
                pc = pred[c]
                par[c] = c + 1
                if pc == -1:
                    c = -1
                    break
                Vc += gap[c]
                c = pc
            if c == -1:
                maxval = v0; pred[e] = -1
            else:
                gap[e] = Vc - v0; pred[e] = c
        tail = e; Vlast = v0
        q = prv[j] if prv[j] > 1 else 1
        b = find(q)
        Vlast += 1
        if pred[b] == -1:
            maxval += 1
        else:
            gap[b] -= 1
            if gap[b] == 0:
                a = pred[b]
                par[a] = a + 1
                if pred[a] == -1:
                    pred[b] = -1
                else:
                    gap[b] = gap[a]; pred[b] = pred[a]
        v = maxval + R[j]
        if v > ans: ans = v
    return ans

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    A = [int(x) for x in data[1:1+N]]
    print(solve(N, A))

main()

