        seen.add(A[i]); L[i] = len(seen)
    R = [0]*(N+2); seen = set()
    for j in range(N, 0, -1):
        R[j] = len(seen); seen.add(A[j])
    size = 1
    while size < N + 2: size *= 2
    BIG = 10**9
    NEG = -4*BIG
    t = [NEG]*(2*size); d = [0]*(2*size)
    for i in range(1, N+1):
        t[size+i] = L[i] - BIG
    for x in range(size-1, 0, -1):
        t[x] = max(t[2*x], t[2*x+1])
    last = {}
    ans = 0
    for j in range(1, N+1):
        p = last.get(A[j], 0); last[A[j]] = j
        if j < 2 or j > N-1:
            continue
        for (l, r, v) in ((j-1, j, BIG), (max(p,1), j, 1)):
            l += size; r += size
            l0 = l; r0 = r - 1
            while l < r:
                if l & 1:
                    t[l] += v; d[l] += v; l += 1
                if r & 1:
                    r -= 1; t[r] += v; d[r] += v
                l >>= 1; r >>= 1
            x = l0 >> 1
            while x:
                a = t[2*x]; b = t[2*x+1]
                t[x] = (a if a > b else b) + d[x]; x >>= 1
            x = r0 >> 1
