def greedy(a):
    n=len(a);h=n//2;i=0
    for j in range(h,n):
        if i<h and 2*a[i]<=a[j]: i+=1
    return i
def brute(a):
    n=len(a);best=0
    # max matching in bipartite-like: pairs (x,y) with 2x<=y, each used once
    from functools import lru_cache
    @lru_cache(None)
    def f(mask):
        # first unused index i lowest
        best=0
        free=[k for k in range(n) if not mask>>k&1]
        for x,y in itertools.combinations(free,2):
            if 2*a[x]<=a[y] or 2*a[y]<=a[x]:
                best=max(best,1+f(mask|1<<x|1<<y))
        return best
    return f(0)
