from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        D = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        def nxt(v):
            return 0 if v == 2 else 2

        F = [[[0] * m for _ in range(n)] for _ in range(4)]
        L = [[[0] * m for _ in range(n)] for _ in range(4)]
        rows_up = range(n)
        rows_down = range(n - 1, -1, -1)
        cols_up = range(m)
        cols_down = range(m - 1, -1, -1)
        for k, (dr, dc) in enumerate(D):
            Fk = F[k]
            Lk = L[k]
            ri = rows_up if dr == 1 else rows_down
            ci = cols_up if dc == 1 else cols_down
            for i in ri:
                pi = i - dr
                for j in ci:
                    g = grid[i][j]
                    if g == 1:
                        Fk[i][j] = 1
                    elif g == 0 or g == 2:
                        pj = j - dc
                        if 0 <= pi < n and 0 <= pj < m:
                            f = Fk[pi][pj]
                            if f > 0 and g == nxt(grid[pi][pj]):
                                Fk[i][j] = f + 1
            ri2 = rows_down if dr == 1 else rows_up
            ci2 = cols_down if dc == 1 else cols_up
            for i in ri2:
                si = i + dr
                for j in ci2:
                    g = grid[i][j]
                    sj = j + dc
                    val = 1
                    if 0 <= si < n and 0 <= sj < m and grid[si][sj] == nxt(g):
                        val = 1 + Lk[si][sj]
                    Lk[i][j] = val
        best = 0
        for k in range(4):
            k2 = (k + 1) % 4
            Fk = F[k]
            L2 = L[k2]
            for i in range(n):
                for j in range(m):
                    f = Fk[i][j]
                    if f > 0:
                        c = f + L2[i][j] - 1
                        if c > best:
                            best = c
        return best

