from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def cnt(o, e, q):
            if o + e == 0:
                return 1
            if q == 1:
                ok = (o == e or o == e + 1)
            else:
                ok = (e == o or e == o + 1)
            return factorial(o) * factorial(e) if ok else 0

        used = [False] * (n + 1)
        res = []
        odd = (n + 1) // 2
        even = n // 2
        prev_par = -1
        for _ in range(n):
            chosen = False
            for v in range(1, n + 1):
                if used[v]:
                    continue
                p = v & 1
                if prev_par != -1 and p == prev_par:
                    continue
                o = odd - (1 if p == 1 else 0)
                e = even - (1 if p == 0 else 0)
                c = cnt(o, e, 1 - p)
                if c < k:
                    k -= c
                else:
                    used[v] = True
                    res.append(v)
                    if p == 1:
                        odd -= 1
                    else:
                        even -= 1
                    prev_par = p
                    chosen = True
                    break
