class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        full = (1 << k) - 1
        def rot(m, s):
            if s == 0:
                return m
            return ((m << s) | (m >> (k - s))) & full
        w = [0] * h
        p = [1 % k] * n
        for i in range(1, n):
            p[i] = p[i - 1] * 10 % k
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w[i] = p[i]
            else:
                w[i] = (p[i] + p[j]) % k
        f = [0] * (h + 1)
        f[h] = 1
        for i in range(h - 1, -1, -1):
            m = 0
            lo = 1 if i == 0 else 0
            for d in range(lo, 10):
                m |= rot(f[i + 1], d * w[i] % k)
            f[i] = m
        if f[0] == 0:
            return ""
        digits = [0] * h
        cur = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                s = (cur + d * w[i]) % k
                need = (-s) % k
                if (f[i + 1] >> need) & 1:
                    digits[i] = d
                    cur = s
                    break
        res = [0] * n
        for i in range(h):
            res[i] = digits[i]
            res[n - 1 - i] = digits[i]
        return "".join(map(str, res))

