from collections import deque
from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nge = [n]*n
        st = []
        for i in range(n-1, -1, -1):
            while st and nums[st[-1]] <= nums[i]:
                st.pop()
            nge[i] = st[-1] if st else n
            st.append(i)
        S = [0]*(n+1)
        for i in range(n-1, -1, -1):
            S[i] = nums[i]*(nge[i]-i) + S[nge[i]]
        pre = [0]*(n+1)
        for i in range(n):
            pre[i+1] = pre[i] + nums[i]
        dq = deque()
        ans = 0
        r = -1
        for l in range(n):
            while dq and dq[0] < l:
                dq.popleft()
            if r < l - 1:
                r = l - 1
            while r + 1 < n:
                c = r + 1
                if dq and nums[dq[0]] >= nums[c]:
                    p = dq[0]
                else:
                    p = c
                cost = S[l] - S[p] + nums[p]*(c - p + 1) - (pre[c+1] - pre[l])
                if cost > k:
                    break
                while dq and nums[dq[-1]] < nums[c]:
                    dq.pop()
                dq.append(c)
                r = c
            ans += r - l + 1
        return ans

