from bisect import bisect_left

def find_all(t, s):
    n, m = len(s), len(t)
    if m == 0:
        return list(range(n + 1))
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k and t[i] != t[k]:
            k = pi[k - 1]
        if t[i] == t[k]:
            k += 1
        pi[i] = k
    res = []
    k = 0
    for i in range(n):
        while k and s[i] != t[k]:
            k = pi[k - 1]
        if s[i] == t[k]:
            k += 1
        if k == m:
            res.append(i - m + 1)
            k = pi[k - 1]
    return res

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        lA, lB, lC = len(A), len(B), len(C)
        oA = find_all(A, s)
        oB = find_all(B, s)
        oC = find_all(C, s)
        if not oA or not oB or not oC:
            return -1
        best = -1
        nB, nC = len(oB), len(oC)
        for a in oA:
            i = bisect_left(oB, a + lA)
            if i == nB:
                break
            b = oB[i]
            j = bisect_left(oC, b + lB)
            if j == nC:
                continue
            L = oC[j] + lC - a
            if best < 0 or L < best:
                best = L
        return best

