import random,time
def fast(n,P):
    tree=[0]*(n+1)
    for i in range(1,n+1):
        tree[i]+=1
        j=i+(i&-i)
        if j<=n: tree[j]+=tree[i]
    LOG=1
    while (LOG<<1)<=n: LOG<<=1
    res=[0]*(n+1)
    for i in range(n,0,-1):
        rem=P[i-1]; pos=0; step=LOG
        while step:
            q=pos+step
            if q<=n and tree[q]<rem:
                pos=q; rem-=tree[q]
            step>>=1
        p=pos+1; res[p]=i
        j=p
        while j<=n:
            tree[j]-=1; j+=j&-j
    return " ".join(map(str,res[1:]))
def brute(n,P):
    A=[]
    for i in range(1,n+1):
        A=A[:P[i-1]-1]+[i]+A[P[i-1]-1:]
    return " ".join(map(str,A))
