import sys,random
def main():
    data=sys.stdin.read().split()
    K=int(data[0]); S=data[1]; T=data[2]
    n=len(S); m=len(T)
    if abs(n-m)>K:
        print("No"); return
    M=(1<<61)-1
    B=random.randrange(10**6,10**9)
    def build(s):
        h=[0]*(len(s)+1)
        x=0
        for idx,c in enumerate(s):
            x=(x*B+ord(c))%M
            h[idx+1]=x
        return h
    hs=build(S); ht=build(T)
    mx=max(n,m)+1
    pw=[1]*(mx+1)
    for i in range(1,mx+1):
        pw[i]=pw[i-1]*B%M
    def sub(h,l,r):
        return (h[r]-h[l]*pw[r-l])%M
    def lcp(i,j):
        hi=min(n-i,m-j)
        if hi<=0: return 0
        if S[i]!=T[j]: return 0
        lo=1
        while lo<hi:
            mid=(lo+hi+1)//2
            if sub(hs,i,i+mid)==sub(ht,j,j+mid):
                lo=mid
            else:
                hi=mid-1
        return lo
    NEG=-10**9
    prev={0:lcp(0,0)}
    if prev.get(m-n,NEG)==n and m-n==0:
        print("Yes"); return
    for e in range(1,K+1):
        cur={}
        for d in range(-e,e+1):
            best=NEG
            if d in prev or (d-1) in prev or (d+1) in prev:
                v=prev.get(d,NEG)
                if v>NEG: best=max(best,v+1)
                v=prev.get(d+1,NEG)
                if v>NEG: best=max(best,v+1)
                v=prev.get(d-1,NEG)
                if v>NEG: best=max(best,v)
            if best==NEG: continue
            bound=min(n,m-d)
            lower=max(0,-d)
            if bound<lower: continue
            if best>bound: best=bound
            if best<lower: continue
            best+=lcp(best,best+d)
            cur[d]=best
        if cur.get(m-n,NEG)==n:
            print("Yes"); return
        prev=cur
    print("No")
main()

