def brute_sc(N,S):
    W=[i for i in range(2*N) if S[i]=='W']
    B=[i for i in range(2*N) if S[i]=='B']
    cnt=0; cntcov=0
    for perm in itertools.permutations(B):
        edges=[(i,i+1) for i in range(2*N-1)]
        for w,b in zip(W,perm): edges.append((w,b))
        # strong connectivity
        adj=[[] for _ in range(2*N)]; radj=[[] for _ in range(2*N)]
        for u,v in edges: adj[u].append(v); radj[v].append(u)
        def reach(g):
            seen={0}; st=[0]
            while st:
                x=st.pop()
                for y in g[x]:
                    if y not in seen: seen.add(y); st.append(y)
            return len(seen)==2*N
        if reach(adj) and reach(radj): cnt+=1
        ok=all(any(b<=i<w for w,b in zip(W,perm)) for i in range(2*N-1))
        if ok: cntcov+=1
    return cnt,cntcov
