class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        INF = float('inf')
        minP = [INF] * k
        ans = -INF
        for j in range(k, n + 1):
            r = (j - k) % k
            if P[j - k] < minP[r]:
                minP[r] = P[j - k]
            v = P[j] - minP[j % k]
            if v > ans:
                ans = v
        return int(ans)

