import random
def fast(a):
    last={};best=-1
    for i,v in enumerate(a):
        if v in last:
            d=i-last[v]+1
            if best==-1 or d<best: best=d
        last[v]=i
    return best
def brute(a):
    n=len(a);best=-1
    for l in range(n):
        for r in range(l,n):
            sub=a[l:r+1]
            if any(sub.count(x)>1 for x in sub):
                L=r-l+1
                if best==-1 or L<best: best=L
    return best
for _ in range(2000):
    n=random.randint(1,9)
    a=[random.randint(1,4) for _ in range(n)]
    assert fast(a)==brute(a),a
print("ok")

