class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        for _ in range(t):
            new = [0] * 26
            for i in range(25):
                new[i + 1] = cnt[i]
            new[0] = (new[0] + cnt[25]) % MOD
            new[1] = (new[1] + cnt[25]) % MOD
            cnt = new
        return sum(cnt) % MOD

