import sys
from itertools import permutations
def main():
    d=sys.stdin.read().split();p=0
    n=int(d[p]);p+=1
    G=[[0]*n for _ in range(n)]
    mg=int(d[p]);p+=1
    for _ in range(mg):
        u=int(d[p])-1;v=int(d[p+1])-1;p+=2
        G[u][v]=G[v][u]=1
    H=[[0]*n for _ in range(n)]
    mh=int(d[p]);p+=1
    for _ in range(mh):
        u=int(d[p])-1;v=int(d[p+1])-1;p+=2
        H[u][v]=H[v][u]=1
    A=[[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1,n):
            A[i][j]=int(d[p]);p+=1
    pairs=[(x,y,A[x][y],H[x][y]) for x in range(n) for y in range(x+1,n)]
    best=None
    for q in permutations(range(n)):
        c=0
        for x,y,a,h in pairs:
            if G[q[x]][q[y]]!=h:
                c+=a
        if best is None or c<best:
            best=c
    print(best)
main()

