from typing import List
class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def sw(v):
            s = str(v)
            res = {v}
            L = len(s)
            for i in range(L):
                for j in range(i + 1, L):
                    t = list(s)
                    t[i], t[j] = t[j], t[i]
                    res.add(int("".join(t)))
            return res
        S = [sw(v) for v in nums]
        n = len(nums)
        cnt = 0
        for i in range(n):
            for j in range(i + 1, n):
                if nums[j] in S[i] or nums[i] in S[j]:
                    cnt += 1
        return cnt

