from typing import List
from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        S = sum(nums)
        cnt = Counter(nums)
        best = None
        for s in cnt:
            o = S - 2 * s
            c = cnt.get(o, 0) - (1 if o == s else 0)
            if c >= 1 and (best is None or o > best):
                best = o
        return best

