from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        LIM = 1000
        mask = (1 << (LIM + 1)) - 1
        bits = [1] * n
        def ok():
            for i in range(n):
                if not (bits[i] >> nums[i]) & 1:
                    return False
            return True
        if ok():
            return 0
        for k, (l, r, v) in enumerate(queries, 1):
            for i in range(l, r + 1):
                bits[i] = ((bits[i] | (bits[i] << v))) & mask
            if ok():
                return k
        return -1

