import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIM = 10000
        comp = [False]*LIM
        comp[0]=comp[1]=True
        for i in range(2,LIM):
            if not comp[i]:
                for j in range(i*i,LIM,i):
                    comp[j]=True
        def isp(x):
            return x >= 2 and not comp[x]
        if isp(n) or isp(m):
            return -1
        if n == m:
            return n
        L = len(str(n))
        pw = [10**i for i in range(L)]
        INF = float('inf')
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            d, v = heapq.heappop(heap)
            if d != dist.get(v, INF):
                continue
            if v == m:
                return d
            for p in pw:
                dig = (v // p) % 10
                cands = []
                if dig < 9:
                    cands.append(v + p)
                if dig > 0:
                    cands.append(v - p)
                for nv in cands:
                    if isp(nv):
                        continue
                    nd = d + nv
                    if nd < dist.get(nv, INF):
                        dist[nv] = nd
                        heapq.heappush(heap, (nd, nv))
        return -1

