class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        NEG = -10**9
        is_t = [False]*n
        for t in targetIndices:
            is_t[t] = True
        pos = {}
        for j, c in enumerate(pattern):
            pos.setdefault(c, []).append(j)
        dp = [NEG]*(m+1)
        dp[0] = 0
        for i in range(n):
            ch = source[i]
            if is_t[i]:
                new = [x+1 if x > NEG else NEG for x in dp]
            else:
                new = dp[:]
            for j in pos.get(ch, ()):
                if dp[j] > NEG and dp[j] > new[j+1]:
                    new[j+1] = dp[j]
            dp = new
        return max(dp[m], 0)

