from collections import deque
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            radj[b].append((a, w))
        def ok(W):
            vis = [False]*n
            vis[0] = True
            cnt = 1
            q = deque([0])
            while q:
                u = q.popleft()
                for v, w in radj[u]:
                    if w <= W and not vis[v]:
                        vis[v] = True
                        cnt += 1
                        q.append(v)
            return cnt == n
        ws = sorted(set(w for _, _, w in edges))
        if not ws or not ok(ws[-1]):
            return -1
        lo, hi = 0, len(ws)-1
        while lo < hi:
            m = (lo+hi)//2
            if ok(ws[m]): hi = m
            else: lo = m+1
        return ws[lo]

