from typing import List
class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = {}
        for a, b in states:
            dp[(a, b)] = cost[0][a] + cost[n-1][b]
        for i in range(1, n // 2):
            ci = cost[i]
            cj = cost[n-1-i]
            nd = {}
            for c1, c2 in states:
                best = INF
                for (a, b), v in dp.items():
                    if a != c1 and b != c2 and v < best:
                        best = v
                nd[(c1, c2)] = best + ci[c1] + cj[c2]
            dp = nd
        return int(min(dp.values()))

