class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        n = len(t)
        while i < n:
            j = i
            while j < n and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j
        total = s.count('1')
        best = 0
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                gain = runs[k - 1][1] + runs[k + 1][1]
                if gain > best:
                    best = gain
        return total + best

