class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        total = 0
        for i, ch in enumerate(s):
            x = ord(ch) - 97
            m = 25 - x
            if stacks[m]:
                j = stacks[m].pop()
                total += i - j
            else:
                stacks[x].append(i)
        return total

