from typing import List
class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        lo, hi = -10**19, 10**19
        base = original[0]
        for i in range(len(original)):
            d = original[i] - base
            u, v = bounds[i]
            lo = max(lo, u - d)
            hi = min(hi, v - d)
        return max(0, hi - lo + 1)
